package com.codex.blacklight.military.aircraft;

import com.codex.blacklight.entity.BlackwatchHelicopter;
import java.util.function.DoubleSupplier;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.phys.Vec3;

/** Authored simpleEngage initial and in-position relocation destination pairs.
 * Native candidate generation/ranking is separate from Minecraft's loaded,
 * swept-body route check; no terrain is requested or generated by this adapter.
 */
final class HelicopterCombatDestination {
    private static final float FREE_WIDTH=18,MAX_HEIGHT=395;
    private HelicopterCombatDestination(){}

    interface Environment {
        float groundAt(Vec3 point);
        float areaHeight(Vec3 point,float width);
        boolean pointAvailable(Vec3 point,float radius);
        boolean clearRoute(Vec3 point);
    }
    private record Profile(float minimum,float maximum,float angle,float heightDifference,float minimumHeight,float minimumMove,int tries,boolean firstValid){}

    static Vec3 find(BlackwatchHelicopter craft,Vec3 observedTarget,boolean hydra,boolean targetHelicopter,HelicopterAirspace space){
        if(craft==null||space==null||craft.isRemoved()||!(craft.level() instanceof ServerLevel level))return null;
        Vec3 origin=craft.position();
        return find(origin,observedTarget,hydra,targetHelicopter,level.random::nextFloat,environment(craft,space,origin));
    }

    /** The caller owns the authored Reaction branch and decides when to relocate. */
    static Vec3 reposition(BlackwatchHelicopter craft,Vec3 observedTarget,HelicopterAirspace space){
        if(craft==null||space==null||craft.isRemoved()||!(craft.level() instanceof ServerLevel level))return null;
        Vec3 origin=craft.position();
        return reposition(origin,observedTarget,level.random::nextFloat,environment(craft,space,origin));
    }

    private static Environment environment(BlackwatchHelicopter craft,HelicopterAirspace space,Vec3 origin){
        float yaw=craft.getYRot();
        return new Environment(){
            public float groundAt(Vec3 point){return space.groundAt(point);}
            public float areaHeight(Vec3 point,float width){return space.areaHeight(point,width);}
            public boolean pointAvailable(Vec3 point,float radius){return space.pointAvailable(point,radius,craft);}
            public boolean clearRoute(Vec3 point){return craft.clearAirRoute(origin,point,origin,yaw);}
        };
    }

    static Vec3 find(Vec3 craft,Vec3 target,boolean hydra,boolean targetHelicopter,DoubleSupplier random,Environment environment){
        float minimumHeight=hydra?15:targetHelicopter?0:8;
        return pair(craft,target,random,environment,
                new Profile(hydra?20:10,hydra?35:25,90,targetHelicopter&&!hydra?60:40,minimumHeight,8,20,false),
                new Profile(hydra?10:5,40,180,100,minimumHeight,5,20,false));
    }

    static Vec3 reposition(Vec3 craft,Vec3 target,DoubleSupplier random,Environment environment){
        // startup_fig offsets89308 and89804: relocation is independent of
        // target class and uses firstValid only in its10-attempt primary round.
        return pair(craft,target,random,environment,
                new Profile(10,30,90,20,8,8,10,true),
                new Profile(5,40,180,100,8,5,20,false));
    }

    private static Vec3 pair(Vec3 craft,Vec3 target,DoubleSupplier random,Environment environment,Profile primary,Profile fallback){
        if(!HelicopterFlight.finite(craft)||!HelicopterFlight.finite(target)||random==null||environment==null)return null;
        float ground=environment.groundAt(target);
        if(!Float.isFinite(ground))return null; // MC missing/unloaded terrain fails closed.
        Vec3 found=search(craft,target,ground,primary,random,environment);
        if(found!=null)return found;
        return search(craft,target,ground,fallback,random,environment);
    }

    private static Vec3 search(Vec3 craft,Vec3 target,float ground,Profile profile,DoubleSupplier random,Environment environment){
        double dx=craft.x-target.x,dz=craft.z-target.z,length=Math.hypot(dx,dz);
        if(!Double.isFinite(length))return null;
        // 103b95a0 uses target->craft, falling back to +Z at coincident XZ.
        if(length*length<1.0e-10F||length<=1.0e-5F){dx=0;dz=1;}else{dx/=length;dz/=length;}
        Vec3 best=null;double bestHeight=Float.MAX_VALUE;
        for(int i=0;i<profile.tries();i++){
            // Source consumes distance first, angle second; radius is uniform,
            // not area-uniform. Minecraft supplies its own world random stream.
            double radial=random.getAsDouble(),angular=random.getAsDouble();
            if(!Double.isFinite(radial)||!Double.isFinite(angular)||radial<0||radial>=1||angular<0||angular>=1)return null;
            double radius=profile.minimum()+(profile.maximum()-profile.minimum())*radial;
            double angle=Math.toRadians(-profile.angle()+2*profile.angle()*angular),sin=Math.sin(angle),cos=Math.cos(angle);
            Vec3 candidate=new Vec3(target.x+(dx*cos+dz*sin)*radius,target.y,target.z+(dz*cos-dx*sin)*radius);
            float area=environment.areaHeight(candidate,FREE_WIDTH);
            if(!Float.isFinite(area))continue;
            // 103c4bc0: MinHeightDifference is a terrain-relative floor during
            // generation. Offset.y=8 is added to the larger terrain height.
            double y=Math.max(ground+profile.minimumHeight(),Math.max(ground,area)+8);
            // 103c33f0's AirDestination=true branch compares actual Y values.
            // Its ground-height-difference branch is for non-air destinations.
            if(Math.abs(target.y-y)>profile.heightDifference()){
                if(target.y<=y)continue;
                y=target.y; // Too far below the reference: raise to its height.
            }
            if(y>MAX_HEIGHT)continue;
            candidate=new Vec3(candidate.x,y,candidate.z);
            if(!environment.pointAvailable(candidate,FREE_WIDTH*.5F))continue;
            // 103bcfa0 includes vertical movement and accepts equality.
            if(candidate.distanceToSqr(craft)<profile.minimumMove()*profile.minimumMove())continue;
            if(!environment.clearRoute(candidate))continue;
            if(profile.firstValid())return candidate; // 103c51a6, then103c5435 exits.
            // 103bd200 enum1 starts at FLT_MAX, factor defaults to1 when the
            // authored timer hash is absent. Equal-height candidates keep first.
            if(candidate.y<bestHeight){best=candidate;bestHeight=candidate.y;}
        }
        return best;
    }
}
